insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_health1_v1'
from (values
('115.38.c.3',3,'Maya sets a goal to run a 5K in 12 weeks and tracks her progress each Sunday. Which skill is she mainly using?','["Goal setting and self-assessment", "Avoidance", "Peer pressure", "Impulse buying"]'::jsonb,0,'Tracking progress toward a goal builds a healthy self-concept.','original'),
('115.38.c.3',3,'After a poor quiz score, a student reviews what went wrong and plans two changes. This shows a healthy self-concept because the student does what?','["Gives up", "Evaluates honestly and makes a plan to improve", "Blames others", "Hides the score"]'::jsonb,1,'Self-evaluation and decision making support a healthy self-concept.','original'),
('115.38.c.4',3,'Which is a protective factor for teen mental health?','["Untreated stress", "Social isolation", "A supportive relationship with a trusted adult", "Constant bullying"]'::jsonb,2,'Protective factors lower risk and build resilience.','original'),
('115.38.c.4',3,'Adverse childhood experiences, such as growing up with ongoing family conflict, can raise the risk of what later in life?','["Better grades automatically", "Longer sleep always", "Faster running", "Mental and physical health problems"]'::jsonb,3,'Early stress can affect long-term health.','original'),
('115.38.c.9',2,'If a classmate has a nosebleed, which first-aid step is correct?','["Have the person sit and lean slightly forward while pinching the soft part of the nose", "Tilt the head far back", "Lay the person flat", "Put ice down the shirt"]'::jsonb,0,'Leaning forward keeps blood from running down the throat.','original'),
('115.38.c.9',2,'Before giving first aid at an accident scene, you should first do what?','["Move the victim at once", "Check that the scene is safe and call for help", "Leave the area", "Take photos"]'::jsonb,1,'Scene safety protects you and the victim.','original'),
('115.38.c.14',3,'Long-term use of tobacco products is most strongly linked with an increased risk of which condition?','["Lower blood pressure", "Better lung capacity", "Lung disease and cancer", "Stronger bones"]'::jsonb,2,'Tobacco harms the lungs and raises cancer risk.','original'),
('115.38.c.14',3,'Nicotine in vaping products is dangerous for teens because it does what?','["Cures stress", "Improves memory", "Builds muscle", "Can harm the developing brain and cause addiction"]'::jsonb,3,'The teen brain is still developing.','original'),
('115.38.c.20',3,'Fertilization occurs when what happens?','["A sperm cell joins with an egg cell", "Two eggs divide", "An embryo implants", "A hormone is released"]'::jsonb,0,'Fertilization forms a zygote.','original'),
('115.38.c.20',3,'Which behavior supports healthy fetal development during pregnancy?','["Smoking occasionally", "Regular prenatal care and avoiding alcohol and tobacco", "Using alcohol", "Skipping checkups"]'::jsonb,1,'Prenatal care improves outcomes.','original'),
('115.38.c.1.A',2,'A student checks the author, date and sponsor of a website before trusting its health advice. This is an example of what?','["Skimming headlines", "Ignoring labels", "Evaluating the reliability of health information", "Copying a friend''s advice"]'::jsonb,2,'Reliable sources are current and credible.','original'),
('115.38.c.1.A',3,'Which source is most reliable for information about vaccines?','["A celebrity post", "A product ad", "An anonymous video", "The Centers for Disease Control and Prevention"]'::jsonb,3,'Government and medical agencies are reliable sources.','original'),
('115.38.c.1.B',3,'Which strategy helps prevent the spread of a communicable disease such as the flu?','["Getting a flu shot and washing hands often", "Sharing drinks", "Ignoring symptoms", "Skipping sleep"]'::jsonb,0,'Vaccines and hygiene reduce spread.','original'),
('115.38.c.1.B',3,'Which is a non-communicable disease that can be reduced by regular exercise and a balanced diet?','["Measles", "Type 2 diabetes", "The common cold", "Strep throat"]'::jsonb,1,'Lifestyle affects chronic disease risk.','original'),
('115.38.c.1.C',3,'Why is early detection of a disease such as skin cancer important?','["It delays treatment", "It prevents all illness", "Treatment is often more effective when problems are found early", "It makes screening unnecessary"]'::jsonb,2,'Early detection improves outcomes.','original'),
('115.38.c.1.C',3,'A teen notices a mole that is changing in size and color. The best action is to do what?','["Cut it off", "Wait a year", "Ignore it", "See a health care provider"]'::jsonb,3,'Warning signs should prompt a check-up.','original'),
('115.38.c.2.A',2,'Perspective-taking means doing what?','["Trying to understand how a situation looks and feels to someone else", "Winning every argument", "Ignoring feelings", "Giving orders"]'::jsonb,0,'It builds respect and empathy.','original'),
('115.38.c.2.A',2,'Which response shows respect for a friend who is upset about not making the team?','["Changing the subject", "Listening and acknowledging how they feel", "Laughing", "Telling them to get over it"]'::jsonb,1,'Respectful responses acknowledge feelings.','original'),
('115.38.c.2.B',3,'Saying "I feel upset when plans change at the last minute, and I''d like a heads-up" is which style of communication?','["Aggressive", "Passive", "Assertive", "Silent"]'::jsonb,2,'Assertive communication is clear and respectful.','original'),
('115.38.c.2.B',3,'Yelling and name-calling during a disagreement is an example of which communication style?','["Assertive", "Respectful", "Passive", "Aggressive"]'::jsonb,3,'Aggressive communication disregards others.','original'),
('115.38.c.5.A',3,'A friend says they feel hopeless and talks about not wanting to be here. What is the most important thing to do?','["Tell a parent, counselor or other trusted adult right away", "Post about it online", "Wait to see if it passes", "Keep it a secret"]'::jsonb,0,'Telling a trusted adult is a key protective step.','original'),
('115.38.c.5.A',3,'Which is a protective factor against suicide identified by public health agencies?','["Isolation", "Strong connections to family, friends and community", "Access to dangerous items", "Substance use"]'::jsonb,1,'Connectedness protects.','original'),
('115.38.c.5.B',3,'Calling or texting 988, the Suicide and Crisis Lifeline, can help a person who is in crisis by doing what?','["Ignoring them", "Judging them", "Connecting them with trained counselors who can help", "Replacing all other care"]'::jsonb,2,'988 offers free, confidential support.','original'),
('115.38.c.5.B',3,'Using crisis resources such as a hotline reduces risk because it does what?','["Discourages talking", "Delays help", "Increases isolation", "Provides support and a path to help when someone feels overwhelmed"]'::jsonb,3,'Support lowers the likelihood of harm.','original'),
('115.38.c.6.A',2,'On a food label, which item tells you the amount of one portion?','["Serving size", "Brand name", "Barcode", "Recycling symbol"]'::jsonb,0,'Everything on the label is based on serving size.','original'),
('115.38.c.6.A',3,'A snack lists 180 calories per serving and the bag holds 3 servings. How many calories are in the whole bag?','["180", "540", "60", "360"]'::jsonb,1,'180 x 3 = 540.','original'),
('115.38.c.6.B',3,'Which dietary practice is healthy?','["Drinking only soda", "Skipping breakfast daily", "Eating a variety of fruits, vegetables and whole grains", "Eating only fast food"]'::jsonb,2,'Variety supports health.','original'),
('115.38.c.6.B',3,'A diet very high in added sugar is linked to what?','["Lower risk of diabetes", "Better sleep", "Stronger teeth", "Weight gain and tooth decay"]'::jsonb,3,'Added sugar harms health.','original'),
('115.38.c.6.C',3,'Why might a personal dietary plan change over a lifetime?','["Needs change with age, activity level and health", "Taste is the only factor", "Needs never change", "Only the weather matters"]'::jsonb,0,'Calorie and nutrient needs shift.','original'),
('115.38.c.6.C',3,'An athlete training daily usually needs what compared with an inactive person of the same size?','["No water", "More energy (calories) and fluids", "Fewer calories", "Only sugar"]'::jsonb,1,'Activity raises energy needs.','original'),
('115.38.c.7.A',3,'Regular physical activity combined with good nutrition improves quality of life by doing what?','["Reducing focus", "Lowering mood", "Boosting energy, mood and sleep", "Causing fatigue"]'::jsonb,2,'Nutrition and activity work together.','original'),
('115.38.c.7.A',3,'Which pairing best supports bone health?','["Soda and no exercise", "Skipping meals", "Only sitting", "Calcium-rich foods and weight-bearing exercise"]'::jsonb,3,'Both build bone.','original'),
('115.38.c.7.B',3,'Body composition refers to what?','["The proportion of fat, muscle, bone and water in the body", "Only height", "Only weight", "Shoe size"]'::jsonb,0,'It is more informative than weight alone.','original'),
('115.38.c.7.B',3,'To balance energy, a person who takes in more calories than they use will most likely do what?','["Lose weight", "Gain weight over time", "Lose muscle only", "Stay the same always"]'::jsonb,1,'Energy balance affects weight.','original'),
('115.38.c.8.A',3,'Compared with highly processed foods, fresh or minimally processed foods usually have what?','["More added salt", "More additives", "Less added sodium, sugar and unhealthy fat", "Lower nutrition"]'::jsonb,2,'Fresh foods are generally more nutritious.','original'),
('115.38.c.8.A',3,'Which is the best way to prepare chicken to limit added fat?','["Deep fry it", "Bread and fry it", "Cover it in cheese sauce", "Bake or grill it"]'::jsonb,3,'Baking or grilling uses less added fat.','original'),
('115.38.c.8.B',3,'Which combination helps prevent heart disease?','["Regular activity and a diet low in saturated fat and sodium", "Inactivity and fast food", "Energy drinks and no sleep", "Smoking and rest"]'::jsonb,0,'Both choices lower risk.','original'),
('115.38.c.8.B',3,'A diet high in fiber from vegetables and whole grains helps reduce the risk of what?','["Strong immunity loss", "Type 2 diabetes and heart disease", "Faster aging", "Vision gains"]'::jsonb,1,'Fiber supports metabolic and heart health.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Health Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
